public class Main {
    static long countSetBits(long n) {
        if (n <= 0) return 0;
        long total = 0;
        int i = 0;
        while ((1L << i) <= n) {
            long period = 1L << (i + 1);
            long fullCycles = (n + 1) / period;
            total += fullCycles * (1L << i);
            long remainder = (n + 1) % period;
            if (remainder > (1L << i)) {
                total += remainder - (1L << i);
            }
            i++;
        }
        return total;
    }

