import sys

def divide(dividend: int, divisor: int) -> int:
    INT_MAX = 2147483647
    INT_MIN = -2147483648

    if dividend == INT_MIN and divisor == -1:
        return INT_MAX
    if dividend == 0:
        return 0

    sign = -1 if (dividend < 0) ^ (divisor < 0) else 1

    dvd = abs(dividend)
    dvs = abs(divisor)
    quotient = 0

    for i in range(31, -1, -1):
        if (dvd >> i) >= dvs:
            quotient += (1 << i)
            dvd -= (dvs << i)

    res = sign * quotient
    return max(INT_MIN, min(INT_MAX, res))

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    a = int(raw[0])
    b = int(raw[1])
    print(divide(a, b))

